/// Kernel handle, initialized on the first verb call (the ambient kernel
/// needs no init verb - the same first-call init the C++/Python faces use).
/// OnceLock keeps one table authoritative.
fn kernel() -> Result<&'static Kernel> {
    static KERNEL: OnceLock<Kernel> = OnceLock::new();
    if KERNEL.get().is_none() {
        let k = load_kernel()?;
        let _ = KERNEL.set(k);
    }
    // set() above means get() is Some (own write or racing winner); typed
    // error on the unreachable arm - panics never cross the napi boundary (D104).
    KERNEL.get().ok_or_else(|| {
        Error::new(Status::GenericFailure, String::from("kernel table vanished after init"))
    })
}

/// forwarder for `modukit_embed_abi_version` (contracts/modukit_embed.h:128) - calls the
/// typed table ONLY (the C door). The raw i32 channel rides `raw`; C
/// out-params ride named properties as data.
#[napi(js_name = "modukit_embed_abi_version")]
pub fn modukit_embed_abi_version() -> Result<i32> {
    let k = kernel()?;
    let raw = (k.sym.embed_abi_version)();
    Ok(raw)
}

/// forwarder for `modukit_install` (contracts/modukit_embed.h:139) - calls the
/// typed table ONLY (the C door). The raw i32 channel rides `raw`; C
/// out-params ride named properties as data.
#[napi(js_name = "modukit_install")]
pub fn modukit_install(env: Env, manifest_toml: String) -> Result<JsObject> {
    let k = kernel()?;
    let c_manifest_toml = CString::new(manifest_toml).map_err(|e| Error::new(Status::InvalidArg, format!("modukit_install: manifest_toml has an interior NUL ({e})")))?;
    let mut out_plugin_id: *const c_char = ptr::null();

    let raw = (k.sym.install)(c_manifest_toml.as_ptr(), &mut out_plugin_id);
    let mut o = env.create_object()?;
    o.set("raw", raw)?;
    // SAFETY: the kernel returns kernel-owned NUL-terminated static
    // bytes (the install note in contracts/modukit_embed.h); copied out
    // through napi, never freed here.
    let out_plugin_id: String = if out_plugin_id.is_null() {
        String::new()
    } else {
        unsafe { CStr::from_ptr(out_plugin_id) }.to_string_lossy().into_owned()
    };
    o.set("out_plugin_id", out_plugin_id)?;
    Ok(o)
}

